import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadYashovarmanData(){const e=readFileSync(resolve(__dirname,"../../yashovarman-kannauj-explorer/yashovarman-data.js"),"utf-8");return new Function(e+"\nreturn { YASHOVARMAN_INFO, COURT_LITERATURE, HISTORICAL_SOURCES, TIMELINE_EVENTS, REFERENCES };")()}describe("Yashovarman of Kannauj Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadYashovarmanData()}),describe("YASHOVARMAN_INFO metadata",()=>{it("contains correct Yashovarman metadata and Kannauj capital",()=>{expect(e.YASHOVARMAN_INFO.id).toBe("yashovarman-kannauj"),expect(e.YASHOVARMAN_INFO.title).toContain("Yashovarman"),expect(e.YASHOVARMAN_INFO.capital).toContain("Kannauj"),expect(e.YASHOVARMAN_INFO.courtScholars).toContain("Bhavabhuti")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.YASHOVARMAN_INFO.quickStats)).toBe(!0),expect(e.YASHOVARMAN_INFO.quickStats.length).toBe(6)})}),describe("COURT_LITERATURE & HISTORICAL_SOURCES",()=>{it("contains court scholars and historical evidence sources",()=>{expect(Array.isArray(e.COURT_LITERATURE)).toBe(!0),expect(e.COURT_LITERATURE.length).toBeGreaterThanOrEqual(2);const a=e.COURT_LITERATURE.find(e=>"Bhavabhuti"===e.scholar);expect(a).toBeDefined(),expect(a.works).toContain("Malatimadhava"),expect(Array.isArray(e.HISTORICAL_SOURCES)).toBe(!0),expect(e.HISTORICAL_SOURCES.length).toBeGreaterThanOrEqual(4)})}),describe("TIMELINE_EVENTS & REFERENCES",()=>{it("contains reign timeline and reference citations",()=>{expect(Array.isArray(e.TIMELINE_EVENTS)).toBe(!0),expect(e.TIMELINE_EVENTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});